<?php if((string)$this->input->get('module')==='english_rpg'){$rpg_tab='progress';include APPPATH.'views/learn/english_rpg/_tabs.php';} ?><div class="container-xl"><div class="page-header"><div><div class="page-pretitle">Pembelajaran</div><h2 class="page-title">Manajemen Progres Pengguna</h2><p class="text-secondary">Skema terpusat: riwayat dan kontrol akses seluruh modul game.</p></div></div><div class="card my-3"><div class="card-body"><form class="row g-2"><input type="hidden" name="module" value="<?= html_escape((string)$this->input->get('module')); ?>"><div class="col-md-6"><input class="form-control" name="q" value="<?= html_escape($q); ?>" placeholder="Cari nama atau username"></div><div class="col-auto"><button class="btn btn-primary">Cari</button> <a class="btn btn-outline-secondary" href="<?= base_url('learn-progress'.($this->input->get('module')?'?module=english_rpg':'')); ?>">Reset</a></div></form></div></div><div class="card"><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Pengguna</th><th>RPG</th><th>Mini Game</th><th>Flashcard</th><th>Cerita</th><th>Battle</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u):$blocked=array_filter($u['access'],function($a){return !empty($a['is_blocked']);}); ?><tr><td><b><?= html_escape($u['full_name']?:$u['username']); ?></b><small class="d-block text-secondary"><?= html_escape($u['username']); ?></small></td><td><?= (int)$u['rpg_chapters']; ?> chapter</td><td><?= (int)$u['mini_sessions']; ?> sesi</td><td><?= (int)$u['flashcards']; ?> kartu</td><td><?= (int)$u['stories']; ?> attempt</td><td><?= (int)$u['battles']; ?> ronde</td><td><?= $blocked?'<span class="badge bg-danger-lt">Ada akses diblokir</span>':'<span class="badge bg-success-lt">Aktif</span>'; ?></td><td><a class="btn btn-sm btn-primary" href="<?= base_url('learn-progress/user/'.$u['id']); ?>">Kelola & Riwayat</a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
